// Package catalog loads `.noml` translation catalogs for the Nolang toolchain.
//
// It is deliberately a separate package from `i18n`: `i18n` must stay free of
// dependencies so every compiler package can import it without creating a cycle,
// while the catalog reader needs the `.noml` parser that lives in `package`.
//
// Layout:
//
//	src/i18n/catalog/locales/en.noml      generated by cmd/genen (translator template)
//	src/i18n/catalog/locales/zh-CN.noml   hand-maintained translations
//	<project>/locales/<tag>.noml          optional per-project override
//
// English has no runtime catalog: `i18n.T` returns the inline default when the
// language is English, so en.noml is never read by the binary. It exists so
// translators have a complete, sorted template and so the gate can prove it is
// in sync with the source.
package catalog

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/lizongying/nolang/i18n"
	pkg "github.com/lizongying/nolang/package"
)

// LocaleDirName is the directory (relative to a project root) that may hold
// `<tag>.noml` overrides.
const LocaleDirName = "locales"

// EnCatalogHeader is the fixed preamble of the generated en.noml. The generator
// and the freshness gate both render through RenderEn, so this text exists once.
const EnCatalogHeader = "; Nolang message catalog: en\n" +
	"; GENERATED by `make i18n` from i18n.T / i18n.P / i18n.Errorf call sites.\n" +
	"; Do not edit by hand: edit the call site, then run `make i18n`.\n"

// RenderEn renders the English catalog document from id -> inline text, sorted
// by ID for a byte-stable result.
func RenderEn(entries map[string]string) string {
	var sb strings.Builder
	sb.WriteString(EnCatalogHeader)
	sb.WriteString("{\n")
	writeEntries(&sb, entries)
	sb.WriteString("}\n")
	return sb.String()
}

func writeEntries(sb *strings.Builder, entries map[string]string) {
	ids := make([]string, 0, len(entries))
	for id := range entries {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		sb.WriteString("  ")
		sb.WriteString(pkg.NomlQuote(id))
		sb.WriteString(": ")
		sb.WriteString(pkg.NomlQuoteValue(entries[id]))
		sb.WriteString("\n")
	}
}

// DocCatalogSuffix marks a doc catalog: `locales/<tag>.doc.noml`. Doc catalogs
// are a separate FILE, not a section of the message catalog, because the two
// have different key namespaces and different ownership rules:
//
//   - message keys are 8-character base36 IDs assigned by the generator and are
//     fully regenerated on every `make i18n`;
//   - doc keys are the anchors an author wrote in the source (`args.get`), and a
//     value is SEEDED once and then preserved, because its source text lives in
//     a comment rather than at a Go call site.
//
// Keeping them apart lets each gate stay exact: `TestLocaleKeysAndVerbs` can keep
// demanding `^[0-9a-z]{8}$` for every message key, and the doc gate can demand
// that every anchor in a doc catalog still exists in the source.
const DocCatalogSuffix = ".doc.noml"

// IsDocCatalogName reports whether a file name is a doc catalog.
func IsDocCatalogName(name string) bool {
	return strings.HasSuffix(name, DocCatalogSuffix)
}

// DocCatalogHeaderFor is the fixed preamble of a rendered doc catalog.
//
// The text spells out the rule that makes this file unlike en.noml: it holds
// TRANSLATIONS ONLY. An anchor that is not in here falls back to the comment
// text in the .no source, which is exactly what an untranslated block should do.
// Seeding every anchor with its source text would fill the English catalog with
// Chinese, which is the failure mode en.noml was already fixed for.
func DocCatalogHeaderFor(tag string) string {
	return "; Nolang doc catalog: " + tag + "\n" +
		"; Source-comment translations, keyed by the anchor an author wrote in a\n" +
		"; trailing `[label](#anchor)` line. This file holds TRANSLATIONS ONLY: an\n" +
		"; anchor that is absent falls back to the comment text in the .no source, so\n" +
		"; untranslated blocks degrade to the author's language instead of shipping a\n" +
		"; copy of it here. Every key must still exist in some .no source, or the gate\n" +
		"; rejects it as an orphan.\n"
}

// RenderDoc renders a doc catalog, sorted by key.
func RenderDoc(tag string, entries map[string]string) string {
	var sb strings.Builder
	sb.WriteString(DocCatalogHeaderFor(tag))
	sb.WriteString("{\n")
	writeEntries(&sb, entries)
	sb.WriteString("}\n")
	return sb.String()
}

// PruneDocTranslations returns the doc table to render: the committed values,
// restricted to anchors that still exist in the source.
//
// Two deliberate choices, both different from message catalogs:
//
//   - a scanned anchor with no committed value is NOT seeded. The source text is
//     the author's language, and English is a translation target for it, so
//     seeding would put Chinese into en.doc.noml and, worse, would make the
//     catalog claim a translation that no one wrote.
//   - a committed value is preserved verbatim, even if the source comment was
//     reworded. The anchor, not the text, is the key, so rewording must not
//     orphan a translation.
//
// The generator and the freshness gate both call this, so "what `make i18n`
// writes" and "what the gate expects" cannot drift.
func PruneDocTranslations(scanned, existing map[string]string) map[string]string {
	if len(existing) == 0 {
		return nil
	}
	out := make(map[string]string, len(existing))
	for anchor, text := range existing {
		if _, ok := scanned[anchor]; !ok || text == "" {
			continue
		}
		out[anchor] = text
	}
	return out
}

// MissingDocTranslations lists, in sorted order, the anchors the source defines
// but a doc catalog does not translate yet. Used by the generator's report so a
// translator can see the remaining work without diffing two files.
func MissingDocTranslations(scanned, existing map[string]string) []string {
	var out []string
	for anchor := range scanned {
		if _, ok := existing[anchor]; !ok {
			out = append(out, anchor)
		}
	}
	sort.Strings(out)
	return out
}

// alias maps a requested tag onto the tag whose file we actually ship. Chinese
// is split by script: Hans/plain "zh" resolve to the Simplified catalog, while
// Hant and the Traditional-script regions (TW/HK/MO) resolve to zh-TW.
var alias = map[string]string{
	"zh":      "zh-CN",
	"zh-hans": "zh-CN",
	"zh-hant": "zh-TW",
	"zh-tw":   "zh-TW",
	"zh-hk":   "zh-TW",
	"zh-mo":   "zh-TW",
}

// Options configures Init.
type Options struct {
	// Lang is the explicit tag from --lang. Empty with LangSet false means "not
	// requested".
	Lang    string
	LangSet bool
	// ProjectDirs are searched for `locales/<tag>.noml` before the embedded
	// files, most specific first.
	ProjectDirs []string
	// Env reads environment variables (nil = os.Getenv).
	Env func(string) string
	// Warn receives non-fatal notices.
	Warn func(msg string)
}

// Init resolves the language and installs its catalog. It is the only function
// the binaries need to call.
func Init(o Options) error {
	return i18n.Init(i18n.Options{
		Lang:      o.Lang,
		LangSet:   o.LangSet,
		Available: Available(o.ProjectDirs),
		Env:       o.Env,
		Warn:      o.Warn,
		Canonical: Canonical,
		Load: func(tag string) (map[string]string, error) {
			return Load(o.ProjectDirs, tag)
		},
		DocLoad: func(tag string) (map[string]string, error) {
			return LoadDoc(o.ProjectDirs, tag)
		},
	})
}

// LoadDoc reads the doc catalog for tag: project `locales/<tag>.doc.noml` first,
// then the embedded copy. A tag with no doc catalog is not an error — it returns
// nil, nil so that `Doc` simply falls back to the source text.
//
// It resolves through Canonical for the same reason Load does: `zh` must find the
// `zh-CN` file, or a user who typed `--lang=zh` would get untranslated comments
// while messages were translated.
func LoadDoc(projectDirs []string, tag string) (map[string]string, error) {
	tag = Canonical(tag)
	name := tag + DocCatalogSuffix
	for _, dir := range projectDirs {
		if dir == "" {
			continue
		}
		path := filepath.Join(dir, LocaleDirName, name)
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("i18n: reading %s: %w", path, err)
		}
		return parseCatalog(path, data)
	}

	path := "locales/" + name
	data, err := localesFS.ReadFile(path)
	if err != nil {
		// No doc catalog for this tag: untranslated, not broken.
		return nil, nil
	}
	return parseCatalog(path, data)
}

// Canonical maps an alias onto the tag whose file exists. Unknown tags are
// returned unchanged so the caller can decide what to do.
func Canonical(tag string) string {
	if c, ok := alias[strings.ToLower(tag)]; ok {
		return c
	}
	return tag
}

// ProjectDirs returns the default search list, most specific first: the working
// directory, then the enclosing workspace root. Both binaries use this so a
// project's `locales/` override behaves the same for `no` and for the LSP.
func ProjectDirs() []string {
	wd, err := os.Getwd()
	if err != nil {
		return nil
	}
	dirs := []string{wd}
	if root, ok := findWorkspaceRoot(wd); ok && root != wd {
		dirs = append(dirs, root)
	}
	return dirs
}

// findWorkspaceRoot walks up from start looking for workspace.noml.
func findWorkspaceRoot(start string) (string, bool) {
	dir := start
	for {
		if _, err := os.Stat(filepath.Join(dir, pkg.WorkspaceFileName)); err == nil {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// Available lists every tag that has a catalog, project-local first, with the
// aliases appended so the resolver can match a bare "zh" request.
func Available(projectDirs []string) []string {
	seen := map[string]bool{}
	var out []string
	add := func(tag string) {
		if tag == "" || tag == "en" || seen[tag] {
			return
		}
		seen[tag] = true
		out = append(out, tag)
	}

	for _, dir := range projectDirs {
		for _, tag := range tagsInDir(dir) {
			add(tag)
		}
	}
	for _, tag := range embeddedTags() {
		add(tag)
	}

	aliases := make([]string, 0, len(alias))
	for a := range alias {
		aliases = append(aliases, a)
	}
	sort.Strings(aliases)
	for _, a := range aliases {
		if seen[alias[a]] {
			add(a)
		}
	}
	return out
}

// Load reads the catalog for tag: project overrides first, then the embedded
// copy. A project file REPLACES the embedded one wholesale for that tag rather
// than merging key by key — predictable beats clever when the file is also the
// thing a translator edits.
func Load(projectDirs []string, tag string) (map[string]string, error) {
	tag = Canonical(tag)
	for _, dir := range projectDirs {
		if dir == "" {
			continue
		}
		path := filepath.Join(dir, LocaleDirName, tag+".noml")
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("i18n: reading %s: %w", path, err)
		}
		return parseCatalog(path, data)
	}

	path := "locales/" + tag + ".noml"
	data, err := localesFS.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("i18n: no catalog for %q", tag)
	}
	return parseCatalog(path, data)
}

// ParseCatalogData turns a `.noml` catalog document into a flat id -> text map.
// It is the same reader Load uses, exported so the generator can inspect the
// committed file it is about to rewrite (to preserve doc translations) without
// going through the embedded copy.
func ParseCatalogData(path string, data []byte) (map[string]string, error) {
	return parseCatalog(path, data)
}

// parseCatalog turns a `.noml` document into a flat id -> text map. Every value
// must be a string: a nested object or array means the file was hand-edited
// wrong, and failing loudly here beats a silent half-loaded catalog.
func parseCatalog(path string, data []byte) (map[string]string, error) {
	m, err := pkg.ParseNomlMap(data)
	if err != nil {
		return nil, fmt.Errorf("i18n: %s: %w", path, err)
	}
	out := make(map[string]string, len(m))
	for k, v := range m {
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("i18n: %s: value for %q must be a string, got %T", path, k, v)
		}
		out[k] = s
	}
	return out, nil
}

// tagsInDir lists the `<tag>.noml` files directly under dir/locales. Doc
// catalogs (`<tag>.doc.noml`) are skipped: they are not tags of their own, and
// listing them would make `Available` claim a language the messages have no
// catalog for.
func tagsInDir(dir string) []string {
	entries, err := os.ReadDir(filepath.Join(dir, LocaleDirName))
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".noml") || IsDocCatalogName(e.Name()) {
			continue
		}
		out = append(out, strings.TrimSuffix(e.Name(), ".noml"))
	}
	sort.Strings(out)
	return out
}
